  with check (((bucket_id = 'chat-attachments'::text) AND (EXISTS ( SELECT 1
   FROM messages m
  WHERE ((m.id = storage_path_uuid(objects.name, 2)) AND (m.channel_id = storage_path_uuid(objects.name, 1)) AND (m.user_id = auth.uid()))))));

